/* =====================================================================
 * PROMPTS
 * P(answer, category, kind, difficulty, words, alternates)
 * words: "a:adjectives|n:nouns|p:people|l:places|v:verbs"
 * ===================================================================== */

const SLOT_KEYS: Record<string, Exclude<Slot, "cat" | "guess">> = {
  a: "adj",
  n: "noun",
  p: "person",
  l: "place",
  v: "verb",
};

function slug(s: string) {
  return s
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
}

const P = (
  answer: string,
  category: Category,
  kind: string,
  difficulty: Difficulty,
  words: string,
  alts = "",
): Prompt => {
  const w: Prompt["words"] = {};
  for (const part of words.split("|")) {
    const [k, v] = part.split(":");
    const slot = SLOT_KEYS[k.trim()];
    if (slot) w[slot] = csv(v);
  }
  return { id: `${category}-${slug(answer)}`, answer, category, kind, difficulty, words: w, alts: csv(alts) };
};

